<?php
declare(strict_types=1);namespace App\Http\Controllers\Finance;use App\Http\Controllers\Controller;use App\Http\Requests\Finance\FeeTypeRequest;use App\Models\Finance\FeeType;class FeeTypeController extends Controller{public function index(){return view('finance.fee-types.index',['feeTypes'=>FeeType::latest()->paginate(20)]);}public function create(){return view('finance.fee-types.form',['feeType'=>new FeeType]);}public function store(FeeTypeRequest $r){FeeType::create($r->validated()+['active'=>$r->boolean('active')]);return redirect()->route('finance.fee-types.index')->with('success','Jenis tagihan berhasil dibuat.');}public function edit(FeeType $feeType){return view('finance.fee-types.form',compact('feeType'));}public function update(FeeTypeRequest $r,FeeType $feeType){$feeType->update($r->validated()+['active'=>$r->boolean('active')]);return redirect()->route('finance.fee-types.index')->with('success','Jenis tagihan berhasil diperbarui.');}public function toggle(FeeType $feeType){$feeType->update(['active'=>!$feeType->active]);return back()->with('success','Status jenis tagihan diperbarui.');}}
